"OLAYLAR_ORTACAG_ORTADOGU:0813-09-24:0":{"b": ["Na kraju opsade Bagdada ubijen Emin (u noći 24. muharrema 198); Memun preuzeo hilafet.", "4fc1fe32"], "d": ["Na kraju opsade Bagdada ubijen Emin (u noći 24. muharrema 198); Memun preuzeo hilafet.", "4fc1fe32"]},
"OLAYLAR_ORTACAG_ORTADOGU:0815-08-11:0":{"b": ["Ibrahim b. Musa zauzeo Sanu (200/815): Jemen izašao iz ruku abasidskih namjesnika", "49e27fe7"], "d": ["Alidski pobunjenik Ibrahim b. Musa porazio je Memunove jedinice i zauzeo Sanu (200/815); dok ga Hamdeveyh b. Mahan nije porazio i proglasio nezavisnost (203/818), grad je izašao iz faktičke uprave Abasidskog hilafeta.", "dc150649"]},
"OLAYLAR_ORTACAG_ORTADOGU:0820-06-17:0":{"b": ["Isa b. Jezid el-Dželudi uklonio Hamdeveyha (205/820): Sana se vratila pod upravu abasidskih namjesnika", "167a2fb1"], "d": ["Hamdeveyha b. Mahana, koji je proglasio nezavisnost, uklonio je Isa b. Jezid el-Dželudi (205/820); Sanom i okolinom do 232 (847) upravljali su abasidski namjesnici poslani iz Bagdada. Tim datumom u atlasu se završava praznina za Sanu (815-820) i počinje razdoblje Abasidskog hilafeta.", "72c4a623"]},
"OLAYLAR_ORTACAG_ORTADOGU:0833-08-09:0":{"b": ["Memun umro blizu Bedenduna u pohodu na Bizant (18. redžeb 218); halifa postao njegov brat Mutasim.", "fa3c1a4c"], "d": ["Memun umro blizu Bedenduna u pohodu na Bizant (18. redžeb 218); halifa postao njegov brat Mutasim.", "fa3c1a4c"]},
"OLAYLAR_ORTACAG_ORTADOGU:0836-01-01:0":{"b": ["Mutasim osnovao Samaru i tamo premjestio središte hilafeta.", "34873200"], "d": ["Mutasim osnovao Samaru i tamo premjestio središte hilafeta.", "34873200"]},
