"OLAYLAR_ORTACAG_ORTADOGU:1291-07-14:0":{"b": ["Memluci zauzeli Tir; krstaška obalna država (Jeruzalemsko kraljevstvo) prestala", "f52aa213"], "d": ["Memluci zauzeli Tir; krstaška obalna država (Jeruzalemsko kraljevstvo) prestala", "f52aa213"]},
"OLAYLAR_ORTACAG_ORTADOGU:1310-10-03:0":{"b": ["Historičara Ebu l-Fidu memlučki sultan imenovao namjesnikom Hame (8. džumadel-ula 710).", "8dbf5f8f"], "d": ["Historičara Ebu l-Fidu memlučki sultan imenovao namjesnikom Hame (8. džumadel-ula 710).", "8dbf5f8f"]},
"OLAYLAR_ORTACAG_ORTADOGU:1312-08-30:0":{"b": ["Ebu l-Fida s titulom 'el-Melik es-Salih' postao melik Hame (25. rebiul-ahir 712).", "e03a1512"], "d": ["Ebu l-Fida s titulom 'el-Melik es-Salih' postao melik Hame (25. rebiul-ahir 712).", "e03a1512"]},
