"OLAYLAR_ORTACAG_ORTADOGU:1378-05-08:0":{"b": ["El-Melik el-Adil Fahruddin ulazi u listu vladara (780/1378, početak hidžretske godine).", "0c952ea6"], "d": ["El-Melik el-Adil Fahruddin ulazi u listu vladara (780/1378, početak hidžretske godine).", "0c952ea6"]},
